"""The catalog package __init__ is GENERATED by scripts/sync_python_layout.py.

Guards the root cause of the catalog SyntaxError: the generator template must
itself compile, and the file on disk must equal the template byte for byte so
a hand-edit or a broken template fails CI instead of shipping.
"""
from __future__ import annotations

import importlib.util
from pathlib import Path

ROOT = Path(__file__).resolve().parents[3]
SCRIPT = ROOT / "scripts" / "sync_python_layout.py"
GENERATED = ROOT / "python" / "src" / "ux_channel" / "catalog" / "__init__.py"


def _template() -> str:
    spec = importlib.util.spec_from_file_location("_sync_python_layout", SCRIPT)
    assert spec and spec.loader
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod.CATALOG_INIT


def test_generator_template_compiles() -> None:
    compile(_template(), "catalog/__init__.py (template)", "exec")


def test_generated_catalog_init_matches_template() -> None:
    assert GENERATED.read_text(encoding="utf-8") == _template(), (
        "catalog/__init__.py drifted from CATALOG_INIT; regenerate with "
        "scripts/sync_python_layout.py instead of hand-editing"
    )
